def esc(value):
    return html.escape(str(value), quote=True)


def url(lc, slug):
    return f"/{lc}/" if slug == "index" else f"/{lc}/{slug}.html"


def absurl(lc, slug):
    return SITE + url(lc, slug)


def nav(lc):
    words = ui[lc][0].split("|")
    links = [("vision", words[0]), ("digital-payments", words[1]), ("payment-infrastructure", words[2]), ("name-architecture", words[3])]
    return "".join(f'<a href="{url(lc, slug)}">{esc(text)}</a>' for slug, text in links) + f'<a class="pill" href="{ACQ}" rel="nofollow sponsored">{esc(words[4])}</a>'


def body(lc, idx, slug, cat, title):
    u = ui[lc]
    c = copy[lc]
    local_cat = cats[lc][cat]
    intro = c[1].format(cat=local_cat)
    lab = labels[lc]
    ins = insights[lc]
    cards = "".join(f'<article class="mini"><span>{esc(lab[(idx + j) % 6])}</span><p>{esc(ins[(idx + j) % 4])}</p></article>' for j in range(4))
    related = "".join(f'<a href="{url(lc, pages[(idx + k) % 30][0])}">{esc(titles[lc][(idx + k) % 30])}</a>' for k in (1, 7, 13))
    flow = f'<div class="flow"><b>{esc(lab[0])}</b><i></i><b>{esc(lab[1])}</b><i></i><b>{esc(lab[2])}</b></div>'
    if slug == "sitemap":
        items = "".join(f'<li><a href="{url(lc, p[0])}">{esc(titles[lc][i])}</a><span>{esc(cats[lc][p[1]])}</span></li>' for i, p in enumerate(pages))
        return f'<section class="hero compact"><p class="kicker">{esc(c[0])}</p><h1>{esc(title)}</h1><p>{esc(intro)}</p></section><section class="index-list"><ol>{items}</ol></section>'
    if slug == "faq":
        return f'<section class="hero split"><div><p class="kicker">{esc(c[0])}</p><h1>{esc(title)}</h1><p>{esc(intro)}</p></div><aside class="notice"><b>{esc(u[9])}</b><p>{esc(u[10])}</p></aside></section><section class="faq"><details open><summary>{esc(c[5])}</summary><p>{esc(c[6])}</p></details><details><summary>{esc(c[7])}</summary><p>{esc(c[8])}</p></details><details><summary>{esc(u[7])}</summary><p>{esc(u[13])}</p></details></section>'
    variants = [
        f'<section class="hero orbit"><p class="kicker">{esc(c[0])}</p><h1>{esc(title)}</h1><p>{esc(intro)}</p><div class="orb" aria-hidden="true"></div></section><section class="mosaic">{cards}</section><section class="essay"><h2>{esc(lab[1])}</h2><p>{esc(c[2])}</p><p>{esc(c[3])}</p></section>',
        f'<section class="hero editorial"><p class="kicker">{esc(local_cat)}</p><h1>{esc(title)}</h1><blockquote>{esc(ins[idx % 4])}</blockquote></section><section class="columns"><p>{esc(intro)}</p><p>{esc(c[2])}</p><p>{esc(c[4])}</p></section><section class="rulebook">{cards}</section>',
        f'<section class="hero dashboard"><div><p class="kicker">{esc(c[0])}</p><h1>{esc(title)}</h1><p>{esc(intro)}</p></div>{flow}</section><section class="panel-grid">{cards}</section>',
        f'<section class="hero minimal"><p class="kicker">{esc(u[14])}</p><h1>{esc(title)}</h1></section><section class="deep"><p class="lead">{esc(intro)}</p><p>{esc(c[2])}</p><p>{esc(c[3])}</p><p>{esc(c[4])}</p></section>',
        f'<section class="hero stack"><p class="kicker">{esc(local_cat)}</p><h1>{esc(title)}</h1><p>{esc(intro)}</p></section><section class="timeline"><div><b>01</b><p>{esc(c[2])}</p></div><div><b>02</b><p>{esc(c[3])}</p></div><div><b>03</b><p>{esc(c[4])}</p></div></section>',
        f'<section class="hero conversion"><div><p class="kicker">{esc(c[0])}</p><h1>{esc(title)}</h1><p>{esc(intro)}</p><a class="button" href="{ACQ}" rel="nofollow sponsored">{esc(u[1])}</a></div><aside>{cards}</aside></section>',
        f'<section class="hero blueprint"><p class="kicker">{esc(local_cat)}</p><h1>{esc(title)}</h1><p>{esc(intro)}</p>{flow}</section><section class="essay framed"><h2>{esc(lab[4])}</h2><p>{esc(c[2])}</p><p>{esc(c[4])}</p></section>',
        f'<section class="hero magazine"><p class="kicker">{esc(c[0])}</p><h1>{esc(title)}</h1><p>{esc(intro)}</p></section><section class="feature-band"><h2>{esc(lab[5])}</h2><p>{esc(c[3])}</p></section><section class="mosaic offset">{cards}</section>',
    ]
    return variants[idx % 8] + f'<section class="notice"><b>{esc(u[9])}</b><p>{esc(u[10])}</p></section><section class="related"><h2>{esc(u[11])}</h2>{related}</section><section class="cta"><h2>{esc(u[12])}</h2><p>{esc(u[13])}</p><a class="button" href="{ACQ}" rel="nofollow sponsored">{esc(u[7])}</a></section>'


def render(lc, idx, page):
    slug, cat, _base, summary = page
    u = ui[lc]
    title = titles[lc][idx]
    desc = summary if lc == "en" else summary_prefix[lc] + cats[lc][cat]
    alternates = "\n".join(f'<link rel="alternate" hreflang="{langs[x][1]}" href="{absurl(x, slug)}">' for x in langs)
    alternates += f'\n<link rel="alternate" hreflang="x-default" href="{absurl("en", slug)}">'
    schema = {"@context": "https://schema.org", "@type": "WebPage", "name": title, "description": desc, "url": absurl(lc, slug), "isPartOf": {"@type": "WebSite", "name": "BridgeToPay.com", "url": SITE}, "inLanguage": langs[lc][1]}
    if slug == "faq":
        c = copy[lc]
        schema = {"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": c[5], "acceptedAnswer": {"@type": "Answer", "text": c[6]}}, {"@type": "Question", "name": c[7], "acceptedAnswer": {"@type": "Answer", "text": c[8]}}]}
    langlinks = "".join(f'<a href="{url(x, slug)}" hreflang="{langs[x][1]}">{x.upper()}</a>' for x in langs)
    crumb = f'<nav class="crumb" aria-label="{esc(u[5])}"><a href="{url(lc, "index")}">{esc(u[2])}</a><span>/</span><span>{esc(title)}</span></nav>'
    return f'''<!doctype html>
<html lang="{langs[lc][1]}" dir="{langs[lc][2]}">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>{esc(title)} | BridgeToPay.com</title>
<meta name="description" content="{esc(desc)}"><meta name="robots" content="index,follow,max-image-preview:large">
<link rel="canonical" href="{absurl(lc, slug)}">
{alternates}
<meta property="og:title" content="{esc(title)} | BridgeToPay.com"><meta property="og:description" content="{esc(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{absurl(lc, slug)}">
<link rel="preload" href="/assets/styles.css" as="style"><link rel="stylesheet" href="/assets/styles.css"><script src="/assets/app.js" defer></script>
<script type="application/ld+json">{json.dumps(schema, ensure_ascii=False)}</script>
</head>
<body><a class="skip" href="#main">{esc(u[3])}</a><header class="site-head"><a class="brand" href="{url(lc, 'index')}" aria-label="BridgeToPay.com">Bridge<span>To</span>Pay</a><button class="menu" data-menu aria-expanded="false">{esc(u[4])}</button><nav class="nav">{nav(lc)}</nav></header>
<main id="main">{crumb}{body(lc, idx, slug, cat, title)}</main>
<footer><div><b>BridgeToPay.com</b><p>{esc(u[8])}</p></div><div class="langs">{langlinks}</div></footer></body></html>'''


css = r'''﻿:root{
  --bg:#f6f9ff;
  --surface:#ffffff;
  --surface-soft:#eef6ff;
  --text:#0b1f35;
  --muted:#5d7086;
  --line:#dbe7f5;
  --blue:#0757d8;
  --blue-2:#00a3ff;
  --blue-3:#e8f3ff;
  --navy:#071b33;
  --green:#19b887;
  --shadow:0 18px 55px rgba(8,46,92,.11);
  --shadow-soft:0 10px 30px rgba(8,46,92,.07);
  --r:24px;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth;background:var(--bg)}
body{margin:0;font-family:Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,Arial,sans-serif;background:radial-gradient(circle at 10% -10%,#dff0ff 0,transparent 32rem),radial-gradient(circle at 95% 8%,#e8f7ff 0,transparent 28rem),linear-gradient(180deg,#fbfdff 0,#f4f8fd 48%,#eef5fc 100%);color:var(--text);line-height:1.65;overflow-x:hidden;text-rendering:optimizeLegibility}
body:before{content:"";position:fixed;inset:0;background-image:linear-gradient(rgba(7,87,216,.045) 1px,transparent 1px),linear-gradient(90deg,rgba(7,87,216,.045) 1px,transparent 1px);background-size:42px 42px;mask-image:linear-gradient(#000,transparent 72%);pointer-events:none}
a{transition:color .2s ease,border-color .2s ease,background .2s ease,transform .2s ease,box-shadow .2s ease}.skip{position:absolute;left:-999px}.skip:focus{left:1rem;top:1rem;z-index:20;background:var(--blue);color:#fff;padding:.7rem 1rem;border-radius:999px}.site-head{position:sticky;top:0;z-index:10;display:flex;align-items:center;justify-content:space-between;gap:20px;padding:14px clamp(16px,4vw,56px);backdrop-filter:blur(18px);background:rgba(255,255,255,.82);border-bottom:1px solid rgba(219,231,245,.9);box-shadow:0 8px 28px rgba(8,46,92,.05)}.brand{font-size:1.18rem;font-weight:900;letter-spacing:-.045em;color:var(--navy);text-decoration:none;white-space:nowrap}.brand span{color:var(--blue)}.nav{display:flex;gap:8px;align-items:center}.nav a,.langs a,.related a{color:var(--muted);text-decoration:none;border:1px solid transparent;padding:9px 12px;border-radius:999px;font-weight:650}.nav a:hover,.related a:hover,.langs a:hover{border-color:var(--line);background:#fff;color:var(--blue);transform:translateY(-1px);box-shadow:var(--shadow-soft)}.pill,.button{background:linear-gradient(135deg,var(--blue),var(--blue-2));color:#fff!important;border-color:transparent!important;font-weight:850;box-shadow:0 12px 24px rgba(7,87,216,.22)}.pill:hover,.button:hover{box-shadow:0 16px 34px rgba(7,87,216,.28);transform:translateY(-2px)}.menu{display:none;background:#fff;color:var(--navy);border:1px solid var(--line);border-radius:999px;padding:9px 13px;font-weight:800}main{padding:24px clamp(16px,4vw,64px) 78px}.crumb{max-width:1180px;margin:0 auto 18px;color:var(--muted);font-size:.92rem}.crumb a{color:var(--blue);text-decoration:none}.crumb span{margin:0 8px}.hero{max-width:1180px;margin:0 auto 28px;min-height:54vh;border:1px solid var(--line);border-radius:var(--r);padding:clamp(34px,6vw,84px);position:relative;overflow:hidden;box-shadow:var(--shadow);background:linear-gradient(145deg,rgba(255,255,255,.96),rgba(239,247,255,.88))}.hero:after{content:"";position:absolute;inset:auto -12% -38% auto;width:52%;aspect-ratio:1;border-radius:999px;background:radial-gradient(circle,rgba(0,163,255,.18),transparent 64%);pointer-events:none}.hero h1{font-size:clamp(2.35rem,6.6vw,7rem);line-height:.93;letter-spacing:-.075em;margin:.1em 0 .28em;max-width:980px;color:var(--navy)}.hero p,.lead{font-size:clamp(1.03rem,1.8vw,1.28rem);color:var(--muted);max-width:780px}.kicker{text-transform:uppercase;letter-spacing:.16em;color:var(--blue)!important;font-size:.78rem!important;font-weight:900}.orbit .orb{position:absolute;width:430px;height:430px;border-radius:50%;right:-120px;bottom:-150px;background:radial-gradient(circle,rgba(0,163,255,.22),transparent 64%);animation:float 8s ease-in-out infinite}.split,.dashboard,.conversion{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(280px,.85fr);gap:28px;align-items:center}.editorial blockquote{font-family:Georgia,serif;font-size:clamp(1.45rem,2.8vw,2.8rem);line-height:1.15;color:var(--blue);margin:30px 0 0}.minimal{min-height:40vh;background:linear-gradient(180deg,#fff,#eef7ff)}.stack{display:flex;flex-direction:column;justify-content:end}.blueprint{background:linear-gradient(135deg,#fff,rgba(232,243,255,.95))}.magazine{border-radius:44px}.compact{min-height:30vh}.mosaic,.panel-grid,.rulebook{max-width:1180px;margin:24px auto;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.mini{padding:22px;border:1px solid var(--line);border-radius:22px;background:rgba(255,255,255,.92);box-shadow:var(--shadow-soft);transition:transform .25s ease,border-color .25s ease,box-shadow .25s ease}.mini:hover{transform:translateY(-5px);border-color:rgba(7,87,216,.28);box-shadow:0 18px 45px rgba(7,87,216,.12)}.mini span{color:var(--blue);font-weight:900}.mini p{color:var(--muted);margin-bottom:0}.columns,.deep,.essay,.feature-band,.notice,.related,.cta,.faq,.index-list,.timeline{max-width:1180px;margin:24px auto;padding:clamp(24px,4vw,52px);border:1px solid var(--line);border-radius:var(--r);background:rgba(255,255,255,.88);box-shadow:var(--shadow-soft)}.columns{columns:3 260px;gap:34px}.columns p{break-inside:avoid}.framed{border-style:dashed}.flow{display:flex;align-items:center;gap:14px;flex-wrap:wrap}.flow b{padding:16px 18px;border:1px solid var(--line);border-radius:18px;background:#fff;color:var(--navy);box-shadow:var(--shadow-soft)}.flow i{width:70px;height:2px;background:linear-gradient(90deg,var(--blue),var(--blue-2))}.timeline{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.timeline b{font-size:2rem;color:var(--blue)}.timeline p,.essay p,.deep p,.feature-band p,.notice p,.cta p,.faq p{color:var(--muted)}.related{display:flex;gap:12px;flex-wrap:wrap;align-items:center}.related h2{width:100%;color:var(--navy);margin-top:0}.cta{text-align:center;background:linear-gradient(135deg,#fff, #e8f3ff)}.button{display:inline-block;text-decoration:none;border-radius:999px;padding:14px 22px;margin-top:12px}.notice{border-left:4px solid var(--blue)}[dir="rtl"] .notice{border-left:1px solid var(--line);border-right:4px solid var(--blue)}.faq details{border-bottom:1px solid var(--line);padding:18px}.faq summary{cursor:pointer;font-weight:900;color:var(--navy)}.index-list ol{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;padding-left:22px}.index-list li{padding:14px;border:1px solid var(--line);border-radius:16px;background:#fff}.index-list a{color:var(--navy);font-weight:900;text-decoration:none}.index-list span{display:block;color:var(--muted)}footer{display:flex;justify-content:space-between;gap:24px;padding:38px clamp(16px,4vw,64px);border-top:1px solid var(--line);color:var(--muted);background:rgba(255,255,255,.62)}footer b{color:var(--navy)}.langs{display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end}.reveal{opacity:0;transform:translateY(16px);transition:opacity .5s ease,transform .5s ease}.reveal.in{opacity:1;transform:none}@keyframes float{50%{transform:translate3d(-20px,-18px,0) scale(1.04)}}@media(max-width:980px){.nav{gap:4px}.nav a{padding:8px 10px}.mosaic,.panel-grid,.rulebook{grid-template-columns:repeat(2,minmax(0,1fr))}.hero h1{letter-spacing:-.06em}}@media(max-width:800px){.site-head{padding:12px 16px}.menu{display:block}.nav{position:absolute;left:16px;right:16px;top:62px;display:none;flex-direction:column;align-items:stretch;background:rgba(255,255,255,.97);border:1px solid var(--line);padding:12px;border-radius:18px;box-shadow:var(--shadow)}[dir="rtl"] .nav{text-align:right}.nav.open{display:flex}.split,.dashboard,.conversion,.timeline{grid-template-columns:1fr}.mosaic,.panel-grid,.rulebook,.index-list ol{grid-template-columns:1fr}.hero{min-height:auto;border-radius:22px;padding:32px 22px}.hero h1{font-size:clamp(2.25rem,14vw,4.2rem)}main{padding-inline:14px}.columns{columns:1}footer{flex-direction:column}.langs{justify-content:flex-start}.flow i{width:42px}}@media(max-width:440px){.brand{font-size:1.02rem}.hero h1{font-size:2.25rem}.columns,.deep,.essay,.feature-band,.notice,.related,.cta,.faq,.index-list,.timeline{padding:22px 18px}.mini{padding:18px}.nav a,.langs a,.related a{width:100%;text-align:center}.crumb{font-size:.84rem}}@media(prefers-reduced-motion:reduce){*,html{scroll-behavior:auto!important;animation:none!important;transition:none!important}.reveal{opacity:1;transform:none}}
'''

js = r'''document.documentElement.classList.add('js');const btn=document.querySelector('[data-menu]'),nav=document.querySelector('.nav');if(btn&&nav){btn.addEventListener('click',()=>{const open=nav.classList.toggle('open');btn.setAttribute('aria-expanded',String(open));});}const els=[...document.querySelectorAll('section,.mini')];els.forEach(e=>e.classList.add('reveal'));if('IntersectionObserver'in window){const io=new IntersectionObserver((entries)=>{entries.forEach(x=>{if(x.isIntersecting){x.target.classList.add('in');io.unobserve(x.target);}})},{threshold:.08});els.forEach(e=>io.observe(e));}else{els.forEach(e=>e.classList.add('in'));}'''


def main():
    (ROOT / "assets").mkdir(exist_ok=True)
    (ROOT / "assets/styles.css").write_text(css, encoding="utf-8")
    (ROOT / "assets/app.js").write_text(js, encoding="utf-8")
    for lc in langs:
        (ROOT / lc).mkdir(exist_ok=True)
        for idx, page in enumerate(pages):
            filename = "index.html" if page[0] == "index" else f"{page[0]}.html"
            (ROOT / lc / filename).write_text(render(lc, idx, page), encoding="utf-8")
    selector = "".join(f'<a href="/{lc}/">{esc(data[0])}</a>' for lc, data in langs.items())
    (ROOT / "index.html").write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BridgeToPay.com</title><meta name="description" content="Choose a language for BridgeToPay.com."><link rel="canonical" href="{SITE}/"><meta http-equiv="refresh" content="0; url=/en/"><link rel="stylesheet" href="/assets/styles.css"></head><body><main><section class="hero compact"><h1>BridgeToPay.com</h1><p>Choose a language.</p><div class="related">{selector}</div></section></main></body></html>', encoding="utf-8")
    urls = [SITE + "/"] + [absurl(lc, page[0]) for lc in langs for page in pages]
    sitemap = '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n' + "".join(f"<url><loc>{u}</loc></url>\n" for u in urls) + "</urlset>\n"
    (ROOT / "sitemap.xml").write_text(sitemap, encoding="utf-8")
    (ROOT / "robots.txt").write_text("User-agent: *\nAllow: /\nSitemap: https://bridgetopay.com/sitemap.xml\n", encoding="utf-8")
    print(f"generated {len(pages)} core pages x {len(langs)} languages = {len(pages) * len(langs)} localized html files")


if __name__ == "__main__":
    main()
